// One item per photo, or one text item for emails with no photos (news, events, stories).
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const fromRaw = typeof j.from === 'string' ? j.from : (j.from?.text || j.from?.value?.[0]?.address || '');
  const m = fromRaw.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>/);
  const fromName = (m ? m[1] : '').trim() || (j.from?.value?.[0]?.name || '');
  const fromEmail = (m ? m[2] : fromRaw).trim();
  const text = String(j.textPlain || j.text || '').replace(/\r/g, '');
  const body = text.split(/\n--\s*\n|\nOn .+ wrote:\n|\nSent from my/)[0].trim();
  const creditLine = body.match(/^\s*credit\s*:\s*(.+)$/im);
  let credit = creditLine ? creditLine[1].trim() : fromName;
  if (/no credit|anonymous/i.test(body)) credit = '';
  const base = {received: j.date || new Date().toISOString(), from_name: fromName, from_email: fromEmail, credit, subject: j.subject || ''};
  const photos = Object.entries(it.binary || {}).filter(([, b]) => /^image\//.test(b.mimeType || '') || /\.(heic|jpe?g|png|webp)$/i.test(b.fileName || ''));
  if (!photos.length) { out.push({json: {...base, type: 'text', note: body.slice(0, 2000), photo_count: 0}}); continue; }
  photos.forEach(([key, b], n) => out.push({
    json: {...base, type: 'photo', note: body.slice(0, 400), file: b.fileName || `photo-${n + 1}.jpg`, mime: b.mimeType || 'image/jpeg', photo_count: photos.length},
    binary: {photo: b},
  }));
}
return out;

// Gemini request with the photo inline. Brand and posting rules are in the prompt.
const promptFor = note => `You review photos sent in by members of the Needlework Guild of Minnesota (a friendly 501(c)(3) stitching guild, mostly women 30+) for the guild's newsletter, Instagram and Facebook.
Rate how good this photo would be as a real, warm, community post. Good: finished or in-progress needlework shown clearly, members stitching together, events, the library, workshops. Natural light and real moments beat posed perfection.
Problems to flag: blurry, too dark, tilted or sideways, screenshot, heavy filter, cluttered background that hides the work, a pattern cover or someone else's copyrighted design shown as the subject, children, private info (names, addresses, phone numbers), anything unflattering to a person in it.
score: 1 to 10. verdict: post (7+, ready), maybe (5 to 6, usable with a crop or as one slide in a carousel), skip (4 or less).
topic: the best fit for a post folder. what: one plain sentence describing the photo.
people: true if any faces are visible. faces: how many.
caption: one short line to put under the photo on a carousel slide, sentence case, warm and plain, no emoji, no em dashes, with exactly one word wrapped in *asterisks* as an accent.
focus: a CSS object-position to keep the subject in a 4:5 crop, like "center 30%".
Sender's note, for context only: ${note || '(none)'}`;
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'photo');
  const it = items[i];
  out.push({json: {...it.json, gemini_body: JSON.stringify({
    contents: [{parts: [{text: promptFor(it.json.note)}, {inline_data: {mime_type: it.json.mime, data: buf.toString('base64')}}]}],
    generationConfig: {responseMimeType: 'application/json', responseSchema: {type: 'OBJECT', required: ['score', 'verdict', 'topic', 'what', 'people', 'faces', 'issues', 'caption', 'focus'], properties: {
      score: {type: 'INTEGER'}, verdict: {type: 'STRING', enum: ['post', 'maybe', 'skip']},
      topic: {type: 'STRING', enum: ['member-work', 'come-and-stitch', 'tea-and-stitch', 'retreat', 'workshop', 'library', 'meetings', 'other']},
      what: {type: 'STRING'}, people: {type: 'BOOLEAN'}, faces: {type: 'INTEGER'}, issues: {type: 'ARRAY', items: {type: 'STRING'}},
      caption: {type: 'STRING'}, focus: {type: 'STRING'}}}},
  })}, binary: it.binary});
}
return out;

// Merge the rating with the sender info, decide where the photo is saved.
const src = $('Build Gemini request').all();
const slug = s => String(s || 'member').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'member';
return $input.all().map((it, i) => {
  const s = src[i].json;
  let r;
  try { r = JSON.parse(it.json.candidates[0].content.parts[0].text); } catch (e) { r = {score: 0, verdict: 'maybe', issues: ['could not rate, check by hand'], what: '', caption: '', topic: 'other', people: false, faces: 0, focus: 'center'}; }
  const day = new Date(s.received).toISOString().slice(0, 10);
  const ext = (s.file.match(/\.[a-z0-9]+$/i) || ['.jpg'])[0].toLowerCase();
  const name = `${day}-${slug(s.credit || s.from_name)}-${slug(s.file.replace(/\.[^.]+$/, ''))}${ext}`;
  return {json: {
    received: s.received, type: 'photo', from_name: s.from_name, from_email: s.from_email, credit: s.credit, subject: s.subject, note: s.note,
    file: s.file, saved_path: `/Users/grahamivy/.n8n-files/ngm-submissions/photos/${r.verdict}/${name}`,
    score: r.score, verdict: r.verdict, topic: r.topic, what: r.what,
    people: r.people ? `yes (${r.faces})` : 'no', issues: (r.issues || []).join('; '), caption: r.caption, focus: r.focus, status: 'new',
  }, binary: src[i].binary};
});

// Emails with no photos: log the note for the newsletter or a text post.
return $input.all().map(it => ({json: {received: it.json.received, type: 'text', from_name: it.json.from_name, from_email: it.json.from_email,
  credit: it.json.credit, subject: it.json.subject, note: it.json.note, status: 'new'}}));

// One thank-you per email.
const seen = new Set(), out = [];
for (const it of $('Split submissions').all()) {
  const j = it.json;
  if (seen.has(j.from_email + j.subject)) continue;
  seen.add(j.from_email + j.subject);
  const first = (j.from_name || '').split(' ')[0] || 'there';
  const what = j.photo_count === 0 ? 'this in' : j.photo_count === 1 ? 'your photo' : `your ${j.photo_count} photos`;
  const credit = j.credit ? `We'll credit you as "${j.credit}". If you'd like a different name, or no name, just reply and tell us.` : `We won't put a name on it, as you asked.`;
  const people = j.photo_count ? `If anyone in the photos would rather not be posted, let us know and we'll leave those out.\n\n` : '';
  out.push({json: {to: j.from_email, subject: `Re: ${j.subject || 'your submission'}`, text:
`Hi ${first},

Thank you for sending ${what}. We'll look it over for the guild's newsletter, Instagram and Facebook.

${credit}

${people}Needlework Guild of Minnesota

https://needleworkguildmn.org`}});
}
return out;
